mapper.select:
SELECT 
FROM sekai_Draw_lots_payment_order
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{limit}

mapper.update:
UPDATE sekai_Draw_lots_payment_order
SET status = 'PAID',
    paid_time = #{paidTime}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE sekai_Draw_lots_payment_order
SET status = 'CANCELED'
WHERE order_no = #{orderNo}
  AND user_id = #{userId}
  AND status = 'PENDING'
